``` {.python .cell-code}
import polars.selectors as cs

gt_pl_weather.tab_style(
    style=style.fill(color="yellow"),
    locations=loc.body(
        columns=cs.exclude(["date", "time"]),
        rows=pl.col("temp") == pl.col("temp").max()
    )
)
